contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newLimit, uint256 sentAmount, bool openFirst) public payable {
        require(newLimit != 0);
        require(sentAmount != 0);

        if (openFirst) {
            c.OpenToThePublic();
        }
        c.AdjustBetAmounts(newLimit);

        bool reverted;
        if (msg.sender == tx.origin) {
            try c.wager{value: sentAmount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = true;
        }

        uint256 limitAfter = c.currentBetLimit();
        bool stored = c.hasPlayerWagered(address(this));

        assert(
            (limitAfter == newLimit) &&
            ((!openFirst) => reverted) &&
            ((openFirst && sentAmount == newLimit) => (!reverted && stored)) &&
            ((openFirst && sentAmount != newLimit) => reverted)
        );
    }

    receive() external payable {}
}

