    function setUp() public {
        c = new C(address(this), 0);
    }

    function _run(uint256 newLimit, uint256 sentAmount) internal {
        sentAmount = bound(sentAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
