        try c.AdjustBetAmounts(newLimit) {} catch { return; }
        uint256 balanceBefore = address(c).balance;
        bool reverted;
        try c.wager{value: sentAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfter = address(c).balance;
        uint256 limitAfter;
        try c.currentBetLimit() returns (uint256 __r) { limitAfter = __r; } catch { return; }
        bool stored;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { stored = __r; } catch { return; }
        assertTrue(limitAfter == newLimit &&
            (!reverted ? (sentAmount == newLimit && balanceAfter == balanceBefore + sentAmount && stored) : true));
    }

    function testFuzz_run(uint256 newLimit, uint256 sentAmount) public {
