contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 betAmount, uint256 difficultyAmount) public payable {
        require(address(this).balance >= betAmount);
        require(betAmount > 0);

        c.OpenToThePublic();
        c.AdjustBetAmounts(betAmount);
        c.AdjustDifficulty(difficultyAmount);
        c.wager{value: betAmount}();

        uint256 beforeBalance = address(c).balance;

        bool reverted;

        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!(reverted == false) && beforeBalance == address(c).balance);
    }

    receive() external payable {}
}
